import math

def _get_joints(agent_components):
    if isinstance(agent_components, dict):
        return agent_components.get("joints", [])
    return []

def build_agent(sandbox):
    start_x = 10.0
    start_y = 2.5
    # Create a stable chassis with increased density
    chassis = sandbox.add_beam(
        x=start_x, y=start_y, width=2.0, height=0.5, density=5.0
    )
    # Wheel parameters
    wheel_radius = 0.8
    wheel_y = 1.0 + wheel_radius  # Ensure wheels are on ground
    # Add wheels with sufficient friction and proper positioning
    wheel_left = sandbox.add_wheel(x=start_x - 3.0, y=wheel_y, radius=wheel_radius, density=1.0)
    wheel_right = sandbox.add_wheel(x=start_x + 3.0, y=wheel_y, radius=wheel_radius, density=1.0)
    # Set maximum friction (clamped by environment's MAX_BODY_FRICTION)
    sandbox.set_material_properties(wheel_left, friction=1.0)
    sandbox.set_material_properties(wheel_right, friction=1.0)
    # Connect wheels to chassis with pivot joints
    joint_left = sandbox.add_joint(
        chassis, wheel_left, (wheel_left.position.x, wheel_left.position.y), type='pivot'
    )
    joint_right = sandbox.add_joint(
        chassis, wheel_right, (wheel_right.position.x, wheel_right.position.y), type='pivot'
    )
    return {
        "body": chassis,
        "joints": [joint_left, joint_right]
    }

def agent_action(sandbox, agent_body, step_count):
    joints = _get_joints(agent_body)
    torso = agent_body.get("body")
    if torso is None:
        return

    # Stability check
    if torso.position.y < 1.2:
        for j in joints:
            sandbox.set_motor(j, 0, max_torque=2000.0)
        return

    # Forward motion
    motor_speed = -1.0  # Reduced speed to avoid joint limits
    for j in joints:
        sandbox.set_motor(j, motor_speed, max_torque=2000.0)

    # Stop motors once target is reached
    if torso.position.x > 25.0:
        for j in joints:
            sandbox.set_motor(j, 0, max_torque=2000.0)

